#!/usr/bin/env bash
# Agent Node standalone installer; contains only the committed project archive.
set -Eeuo pipefail
if [[ "${1:-}" == --help || "${1:-}" == -h ]]; then
  echo '新 VPS：在 root 登录终端运行 bash install-openhands.sh，按向导选择代理、Tailscale 和订阅登录。'
  echo '可选参数：--proxy|--no-proxy --tailscale|--no-tailscale --login codex|claude|all|none'
  echo '解包到 /opt/agent-node；已有目录时退出。后续可运行 /opt/agent-node/install.sh 重试未完成的首次安装。'
  exit 0
fi
[[ $EUID -eq 0 && "$HOME" == /root ]] || { echo '请先 sudo -i，使用完整 root 登录环境。' >&2; exit 1; }
[[ "$(uname -s)" == Linux ]] || { echo '仅支持 Ubuntu/Debian VPS。' >&2; exit 1; }
target=/opt/agent-node
[[ ! -e "$target" && ! -L "$target" ]] || { echo '/opt/agent-node 已存在；保留现有目录，请使用其中的 install.sh 或分模块操作。' >&2; exit 1; }
mkdir -p /opt
staging="$(mktemp -d /opt/.agent-node-install.XXXXXX)"
trap 'rm -rf -- "$staging"' EXIT
base64 --decode > "$staging/project.tar.gz" <<'AGENT_NODE_ARCHIVE'
